import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

function Games({ onGameWin }) {
  const { subId } = useParams();
  const user = JSON.parse(localStorage.getItem("user"));

  const [games, setGames] = useState([]);
  const [progress, setProgress] = useState({});
  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState(null);

  useEffect(() => {
    async function load() {
      try {
        const gRes = await fetch(`http://localhost:8080/games?subId=${subId || ""}`);
        const gData = await gRes.json();

        const pRes = await fetch(`http://localhost:8080/game_progress?userId=${user?.id || ""}`);
        const pData = await pRes.json();

        setGames(gData.games || []);
        // map progress by game_id for quick lookup
        const map = {};
        (pData.progress || []).forEach((pg) => (map[pg.game_id] = pg));
        setProgress(map);
      } catch (err) {
        console.error("Games load error:", err);
      } finally {
        setLoading(false);
      }
    }

    load();
  }, [subId, user]);

  if (!user) return <h1 style={{ color: "white" }}>Please log in</h1>;

  async function unlockGame(game) {
    if (!user) return;
    setProcessingId(game.id);
    try {
      const res = await fetch("http://localhost:8080/game_progress/unlock", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, game_id: game.id }),
      });
      const data = await res.json();
      if (res.ok) {
        setProgress((p) => ({ ...p, [game.id]: { ...(p[game.id] || {}), unlocked: 1 } }));
        alert(data.message || "Game unlocked");
      } else {
        alert(data.message || "Could not unlock game");
      }
    } catch (err) {
      console.error(err);
      alert("Unlock failed");
    } finally {
      setProcessingId(null);
    }
  }

  async function playGame(game) {
    if (!user) return;
    setProcessingId(game.id);
    try {
      // For now, simulate a game session — call backend to mark completion and award points
      const res = await fetch("http://localhost:8080/game_progress/complete", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, game_id: game.id }),
      });
      const data = await res.json();
      if (res.ok) {
        // update progress and inform parent about XP/score
        setProgress((p) => ({ ...p, [game.id]: { ...(p[game.id] || {}), completed: (p[game.id]?.completed || 0) + 1, total_score: (p[game.id]?.total_score || 0) + (data.awarded_points || game.base_reward) } }));
        alert(data.message || `You earned ${data.awarded_points || game.base_reward} points!`);
        if (onGameWin && data.awarded_points) onGameWin(data.awarded_points, game.subscience_id);
      } else {
        alert(data.message || "Game play failed");
      }
    } catch (err) {
      console.error(err);
      alert("Play failed");
    } finally {
      setProcessingId(null);
    }
  }

  return (
    <section className="page fade-in">
      <h1 className="slide-up">Games</h1>
      <p className="slide-up">Play games to earn points — unlock higher-tier games with coins.</p>

      {loading ? (
        <p className="dashboard-loading">Loading games...</p>
      ) : (
        <div className="games-grid">
          {games.map((g) => {
            const pg = progress[g.id] || {};
            const unlocked = !!pg.unlocked || g.game_number === 1;
            const completed = pg.completed || 0;

            return (
              <div key={g.id} className="card" style={{ marginBottom: 12 }}>
                <h3>Game {g.game_number}</h3>
                <p className="small muted">Reward: {g.base_reward} pts • Cost: {g.coin_cost} coins</p>
                <p>{g.description || "A fun interactive challenge."}</p>

                <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                  {unlocked ? (
                    <>
                      <button className="primary-btn" disabled={processingId === g.id} onClick={() => playGame(g)}>
                        Play
                      </button>
                      <div style={{ alignSelf: "center" }}>{completed > 0 ? `Completed ${completed}x` : "Not played"}</div>
                    </>
                  ) : (
                    <button className="secondary-btn" disabled={processingId === g.id} onClick={() => unlockGame(g)}>
                      Unlock ({g.coin_cost} coins)
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}

export default Games;
